import com.sun.jdi.*;import com.sun.jdi.connect.*;import java.util.*;
public class JdiBgLoad2{static Method find(ReferenceType t,String n,String s){for(Method m:t.methodsByName(n))if(m.signature().equals(s))return m;return null;}
public static void main(String[]a)throws Exception{AttachingConnector c=null;for(AttachingConnector x:Bootstrap.virtualMachineManager().attachingConnectors())if(x.name().equals("com.sun.jdi.SocketAttach"))c=x;Map<String,Connector.Argument>ca=c.defaultArguments();ca.get("hostname").setValue("localhost");ca.get("port").setValue("8700");ca.get("timeout").setValue("5000");VirtualMachine vm=c.attach(ca);try{ThreadReference th=null;for(ThreadReference t:vm.allThreads()){System.out.println("thread "+t.name());if(th==null&&!t.name().equals("main")&&!t.name().toLowerCase().contains("signal")&&!t.name().toLowerCase().contains("jdwp"))th=t;}if(th==null)th=vm.allThreads().get(0);System.out.println("use "+th.name());th.suspend();ClassType sys=(ClassType)vm.classesByName("java.lang.System").get(0);Method load=find(sys,"load","(Ljava/lang/String;)V");try{sys.invokeMethod(th,load,Collections.singletonList(vm.mirrorOf(a[0])),0);System.out.println("loaded");}catch(InvocationException ie){System.out.println("EX "+ie.exception().referenceType().name());}th.resume();}finally{vm.dispose();}}}
